import{browserApi}from'../browser/browser-api.js';import{getSettings,getStats}from'../shared/storage.js';const enabled=document.querySelector('#enabled'),status=document.querySelector('#status');async function render(){const[s,st]=await Promise.all([getSettings(),getStats()]);enabled.checked=s.enabled;status.textContent=s.enabled?'Active · new tabs are fair game':'Inactive · browse normally';document.querySelector('#session-count').textContent=st.sessionCount;document.querySelector('#lifetime-count').textContent=st.lifetimeCount}enabled.addEventListener('change',async()=>{await browserApi.runtime.sendMessage({type:'set-enabled',enabled:enabled.checked});await render()});document.querySelector('#settings').addEventListener('click',()=>browserApi.runtime.openOptionsPage());render();
